



import React, { useState } from 'react';
import { useHistory } from 'react-router-dom';
import './index.css';

const Cadastro = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const history = useHistory();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      // Adicionar lógica para criar uma conta, por exemplo, usando Supabase
      // Aqui você pode substituir pelo código real que cria uma conta no seu backend
      await fakeRegister(email, password); // Substitua esta linha com a sua lógica de cadastro
      setMessage('Seu cadastro foi realizado com sucesso!');
      setTimeout(() => {
        history.push('/');
      }, 3000);
    } catch (error) {
      setMessage('Erro ao realizar cadastro: ' + error.message);
    }
  };

  return (
    <div className="cadastro-container">
      <div className="cadastro-box">
        <h2>Cadastro</h2>
        <form onSubmit={handleSubmit}>
          <div>
            <label>Email</label>
            <input 
              type="email" 
              value={email} 
              onChange={(e) => setEmail(e.target.value)} 
              required 
            />
          </div>
          <div>
            <label>Senha</label>
            <input 
              type="password" 
              value={password} 
              onChange={(e) => setPassword(e.target.value)} 
              required 
            />
          </div>
          <button type="submit">Registrar</button>
        </form>
        {message && <p>{message}</p>}
      </div>
    </div>
  );
};

// Função de exemplo para simular o registro, substitua com a sua lógica real
const fakeRegister = (email, password) => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (email === "erro@exemplo.com") {
        reject(new Error("Email já cadastrado"));
      } else {
        resolve();
      }
    }, 1000);
  });
};

export default Cadastro;
